-- SCCO: esquema exploratório. NÃO pronto para produção.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE organizations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE object_registry (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), object_type TEXT NOT NULL, canonical_name TEXT NOT NULL, lifecycle_status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(id, organization_id));
CREATE TABLE knowledge_objects (id UUID PRIMARY KEY, organization_id UUID NOT NULL, knowledge_type TEXT NOT NULL, owner_object_id UUID REFERENCES object_registry(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY (id, organization_id) REFERENCES object_registry(id, organization_id));
CREATE TABLE knowledge_versions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), knowledge_id UUID NOT NULL REFERENCES knowledge_objects(id), version_number INTEGER NOT NULL CHECK(version_number > 0), title TEXT NOT NULL, content JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'draft', valid_from TIMESTAMPTZ, valid_to TIMESTAMPTZ, recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(), approved_at TIMESTAMPTZ, approved_by UUID REFERENCES object_registry(id), CHECK(valid_to IS NULL OR valid_from < valid_to), UNIQUE(knowledge_id,version_number));
CREATE TABLE predicates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, value_type TEXT NOT NULL, is_multivalued BOOLEAN NOT NULL DEFAULT false, definition JSONB NOT NULL DEFAULT '{}');
CREATE TABLE claims (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), subject_id UUID NOT NULL REFERENCES object_registry(id), predicate_id UUID NOT NULL REFERENCES predicates(id), object_id UUID REFERENCES object_registry(id), literal_value JSONB, scope_id UUID REFERENCES object_registry(id), knowledge_version_id UUID REFERENCES knowledge_versions(id), status TEXT NOT NULL DEFAULT 'proposed', valid_from TIMESTAMPTZ, valid_to TIMESTAMPTZ, recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK ((object_id IS NOT NULL AND literal_value IS NULL) OR (object_id IS NULL AND literal_value IS NOT NULL)), CHECK(valid_to IS NULL OR valid_from < valid_to));
CREATE TABLE source_artifacts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), media_type TEXT NOT NULL, storage_key TEXT NOT NULL, sha256 TEXT NOT NULL, uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now(), metadata JSONB NOT NULL DEFAULT '{}');
CREATE TABLE content_segments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), artifact_id UUID NOT NULL REFERENCES source_artifacts(id), locator JSONB NOT NULL, extracted_text TEXT, metadata JSONB NOT NULL DEFAULT '{}');
CREATE TABLE evidence_links (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), claim_id UUID NOT NULL REFERENCES claims(id), segment_id UUID NOT NULL REFERENCES content_segments(id), relation_type TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(claim_id,segment_id,relation_type));
CREATE TABLE graph_edges (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), source_id UUID NOT NULL REFERENCES object_registry(id), target_id UUID NOT NULL REFERENCES object_registry(id), relation_type TEXT NOT NULL, valid_from TIMESTAMPTZ, valid_to TIMESTAMPTZ, metadata JSONB NOT NULL DEFAULT '{}', CHECK(valid_to IS NULL OR valid_from < valid_to));
CREATE INDEX idx_claims_subject_predicate ON claims(subject_id,predicate_id);
CREATE INDEX idx_claims_scope_status ON claims(scope_id,status);
CREATE INDEX idx_knowledge_versions_object ON knowledge_versions(knowledge_id,version_number DESC);
CREATE INDEX idx_graph_edges_source ON graph_edges(source_id,relation_type);
CREATE INDEX idx_graph_edges_target ON graph_edges(target_id,relation_type);
